:root {
  --ink: #171614;
  --paper: #f6f2ea;
  --accent: #ff6b4a;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: system-ui, sans-serif;
}

.card {
  padding: 24px;
  border: 1px solid #d9d1c4;
  border-radius: 16px;
}

.nav {
  display: flex;
  align-items: center;
  gap: 18px;
  justify-content: space-between;
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}

@media (max-width: 800px) {
  .cards {
    grid-template-columns: 1fr;
  }
}

img {
  max-width: 100%;
  height: auto;
}

.wrap {
  width: min(1120px, calc(100% - 32px));
  margin-inline: auto;
}

@media (max-width: 700px) {
  h1 { font-size: 2.5rem; }
  .nav { flex-direction: column; align-items: flex-start; }
}

:root {
  --paper: #f6f2ea;
  --ink: #171614;
  --accent: #c2410c;
  --focus: #4b45e8;
}

body { background: var(--paper); color: var(--ink); }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }

:root {
  font-family: system-ui, sans-serif;
  color: #171614;
  background: #f6f2ea;
  line-height: 1.6;
}

body { margin: 0; }

.site-header, main, footer {
  width: min(1100px, calc(100% - 32px));
  margin-inline: auto;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
  padding-block: 24px;
}

.hero { padding-block: 64px; }
.hero h1 { font-size: clamp(2.5rem, 7vw, 5rem); line-height: 1; max-width: 800px; }

.project-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

@media (max-width: 700px) {
  .project-grid { grid-template-columns: 1fr; }
}
